// Mediterranean coastal village — late afternoon
// Direct 2D composition. All pixels procedural.

const W_ = W, H_ = H;

function lerp(a,b,t){ return a+(b-a)*t; }
function clamp(v,a,b){ return v<a?a:(v>b?b:v); }
function smooth(t){ return t*t*(3-2*t); }

// ---------- value noise using seeded rng ----------
function makeNoise(seedGrid){
  const N = 256;
  const perm = new Uint8Array(512);
  const p = new Uint8Array(N);
  for(let i=0;i<N;i++) p[i]=i;
  for(let i=N-1;i>0;i--){
    const j = Math.floor(rng()*(i+1));
    const t=p[i]; p[i]=p[j]; p[j]=t;
  }
  for(let i=0;i<512;i++) perm[i]=p[i&255];
  return function(x,y){
    const xi=Math.floor(x)&255, yi=Math.floor(y)&255;
    const xf=x-Math.floor(x), yf=y-Math.floor(y);
    const u=smooth(xf), v=smooth(yf);
    const aa=perm[perm[xi]+yi]/255;
    const ab=perm[perm[xi]+yi+1]/255;
    const ba=perm[perm[xi+1]+yi]/255;
    const bb=perm[perm[xi+1]+yi+1]/255;
    return lerp(lerp(aa,ba,u),lerp(ab,bb,u),v);
  };
}
const noise = makeNoise(12345);
function fbm(x,y,oct){
  let s=0,a=0.5,f=1,norm=0;
  for(let i=0;i<oct;i++){ s+=a*noise(x*f,y*f); norm+=a; a*=0.5; f*=2; }
  return s/norm;
}

// ---------- palette ----------
const stuccoLight = '#f3ecdb';
const stuccoMid = '#e6dcc6';
const stuccoShade = '#c4bcc4';
const roofA = '#c26a44';
const roofB = '#a8502e';
const roofC = '#d98a55';

// ============================================================
// OPAQUE BASE
// ============================================================
ctx.fillStyle = '#e8dfc9';
ctx.fillRect(0,0,W_,H_);

// ---------- sky ----------
function paintSky(){
  const g = ctx.createLinearGradient(0,0,0,H_*0.60);
  g.addColorStop(0,'#bcd6ea');
  g.addColorStop(0.45,'#e8dfc9');
  g.addColorStop(0.82,'#f6d9a8');
  g.addColorStop(1,'#fae3bd');
  ctx.fillStyle = g;
  ctx.fillRect(0,0,W_,H_*0.60);

  // soft hazy clouds
  ctx.save();
  for(let i=0;i<16;i++){
    const cx = random()*W_;
    const cy = 30 + random()*H_*0.32;
    const rw = 130 + random()*240;
    const rh = 16 + random()*30;
    ctx.globalAlpha = 0.10 + random()*0.14;
    const cg = ctx.createRadialGradient(cx,cy,0,cx,cy,rw);
    cg.addColorStop(0,'#ffffff');
    cg.addColorStop(0.6,'#fdf2df');
    cg.addColorStop(1,'rgba(253,242,223,0)');
    ctx.fillStyle = cg;
    ctx.beginPath();
    ctx.ellipse(cx,cy,rw,rh,0,0,Math.PI*2);
    ctx.fill();
  }
  ctx.restore();

  // warm sun glow
  const sg = ctx.createRadialGradient(W_*0.20,H_*0.16,10,W_*0.20,H_*0.16,W_*0.55);
  sg.addColorStop(0,'rgba(255,244,214,0.55)');
  sg.addColorStop(0.35,'rgba(255,235,190,0.22)');
  sg.addColorStop(1,'rgba(255,235,190,0)');
  ctx.fillStyle = sg;
  ctx.fillRect(0,0,W_,H_*0.60);
}

// ---------- distant sea (extended to bottom-right) ----------
function paintSea(){
  const horizonY = H_*0.50;
  // shoreline polygon: left cliff edge slanting down-right to fill whole bottom-right
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(W_*0.30, horizonY);
  ctx.lineTo(W_, horizonY);
  ctx.lineTo(W_, H_);
  ctx.lineTo(W_*0.05, H_);
  ctx.lineTo(W_*0.10, H_*0.90);
  ctx.lineTo(W_*0.18, H_*0.80);
  ctx.lineTo(W_*0.22, H_*0.68);
  ctx.lineTo(W_*0.28, H_*0.58);
  ctx.closePath();

  const g = ctx.createLinearGradient(0,horizonY,0,H_);
  g.addColorStop(0,'#9ab7c8');
  g.addColorStop(0.12,'#4f88ad');
  g.addColorStop(0.42,'#2f74a2');
  g.addColorStop(0.75,'#2a8ba0');
  g.addColorStop(0.9,'#4aabaf');
  g.addColorStop(1,'#6cc5bd');
  ctx.fillStyle = g;
  ctx.fill();

  ctx.clip();

  // hazy horizon band
  const hz = ctx.createLinearGradient(0,horizonY-14,0,horizonY+40);
  hz.addColorStop(0,'rgba(250,232,200,0.85)');
  hz.addColorStop(0.5,'rgba(220,226,232,0.35)');
  hz.addColorStop(1,'rgba(150,180,205,0)');
  ctx.fillStyle = hz;
  ctx.fillRect(0, horizonY-14, W_, 54);

  // deeper patches
  ctx.globalAlpha = 0.28;
  for(let i=0;i<70;i++){
    const y = horizonY + (H_-horizonY)*Math.pow(random(),0.6);
    const x = random()*W_;
    const rw = 40+random()*200;
    const rh = 3+random()*10;
    const gg = ctx.createRadialGradient(x,y,0,x,y,rw);
    gg.addColorStop(0,'#1d4a7a');
    gg.addColorStop(1,'rgba(29,74,122,0)');
    ctx.fillStyle = gg;
    ctx.beginPath();
    ctx.ellipse(x,y,rw,rh,0,0,Math.PI*2);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  // glitter stripes
  for(let i=0;i<600;i++){
    const t = random();
    const y = horizonY + 8 + t*(H_-horizonY-10);
    const depth = t;
    const len = (0.4 + random()*1.8) * (18 + depth*100);
    const x = random()*W_;
    const alpha = (0.08 + random()*0.28) * (1 - depth*0.4);
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = depth > 0.6 ? '#dff4ff' : '#ffe9c8';
    ctx.lineWidth = 0.6 + random()*1.5;
    ctx.beginPath();
    ctx.moveTo(x,y);
    ctx.lineTo(x+len, y + (random()-0.5)*1.4);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // fine turquoise horizontal ripples in the near shallows
  for(let i=0;i<1800;i++){
    const depth = Math.pow(random(),0.4);
    const y = horizonY + (H_-horizonY)*(0.3 + depth*0.7);
    const x = random()*W_;
    const len = 6 + depth*70*random();
    const alpha = 0.05 + depth*0.32*random();
    ctx.globalAlpha = alpha;
    ctx.strokeStyle = depth > 0.75 ? '#bfffe8' : '#e8fbff';
    ctx.lineWidth = 0.4 + random()*1.1;
    ctx.beginPath();
    ctx.moveTo(x,y);
    ctx.lineTo(x+len, y);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;

  // darker deeper ripples
  for(let i=0;i<700;i++){
    const depth = Math.pow(random(),0.5);
    const y = horizonY + (H_-horizonY)*(0.15 + depth*0.55);
    const x = random()*W_;
    const len = 10 + depth*90*random();
    ctx.globalAlpha = 0.05 + random()*0.14;
    ctx.strokeStyle = depth<0.5 ? '#2a5f8a' : '#3a8a96';
    ctx.lineWidth = 0.6 + random()*1.2;
    ctx.beginPath();
    ctx.moveTo(x,y);
    ctx.lineTo(x+len, y+(random()-0.5)*0.6);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  ctx.restore();
}

// ---------- distant headland on left ----------
function paintHeadland(){
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(0, H_*0.50);
  ctx.lineTo(W_*0.04, H_*0.49);
  ctx.lineTo(W_*0.09, H_*0.51);
  ctx.lineTo(W_*0.14, H_*0.55);
  ctx.lineTo(W_*0.20, H_*0.58);
  ctx.lineTo(W_*0.25, H_*0.585);
  ctx.lineTo(W_*0.29, H_*0.55);
  ctx.lineTo(W_*0.31, H_*0.50);
  ctx.lineTo(W_*0.31, H_*0.60);
  ctx.lineTo(0, H_*0.60);
  ctx.closePath();
  const g = ctx.createLinearGradient(0,H_*0.46,0,H_*0.62);
  g.addColorStop(0,'#b5b8c8');
  g.addColorStop(0.5,'#8e96ab');
  g.addColorStop(1,'#6c7d97');
  ctx.fillStyle = g;
  ctx.fill();

  // faint haze over headland
  ctx.globalAlpha = 0.35;
  ctx.fillStyle = '#e8dcc4';
  ctx.fillRect(0, H_*0.50, W_*0.33, H_*0.06);
  ctx.restore();
}

// ---------- building drawing ----------
function lightEdge(x1,y1,x2,y2,width,color,alpha){
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.strokeStyle = color;
  ctx.lineWidth = width;
  ctx.lineCap = 'round';
  ctx.beginPath();
  ctx.moveTo(x1,y1);
  ctx.lineTo(x2,y2);
  ctx.stroke();
  ctx.restore();
}

function drawHouse(cx, baseY, w, h, shade, roofColor, seed, opts){
  opts = opts || {};
  const topY = baseY - h;
  const left = cx - w*0.5;
  const right = cx + w*0.5;
  const leanU = (random()-0.5)*w*0.05;
  const leanL = (random()-0.5)*w*0.05;

  // shadow cast behind house
  if(opts.castShadow){
    ctx.save();
    ctx.globalAlpha = 0.22;
    ctx.fillStyle = '#3a3040';
    ctx.beginPath();
    ctx.moveTo(left-6, baseY+2);
    ctx.lineTo(right+8, baseY+2);
    ctx.lineTo(right+18, baseY+18);
    ctx.lineTo(left-14, baseY+18);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }

  // body
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(left, baseY);
  ctx.lineTo(left+leanL, topY);
  ctx.lineTo(right+leanU, topY);
  ctx.lineTo(right, baseY);
  ctx.closePath();
  const bg = ctx.createLinearGradient(left,topY,right,baseY);
  if(shade){
    bg.addColorStop(0, '#cfc5c8');
    bg.addColorStop(0.6, '#c4bcc4');
    bg.addColorStop(1, '#d4c8cc');
  } else {
    bg.addColorStop(0, '#f6efdf');
    bg.addColorStop(0.55, stuccoMid);
    bg.addColorStop(1, '#cfc4b0');
  }
  ctx.fillStyle = bg;
  ctx.fill();

  // stucco mottling
  ctx.clip();
  const patches = Math.max(8, Math.floor(w*h/700));
  for(let i=0;i<patches;i++){
    const mx = left + random()*w;
    const my = topY + random()*h;
    const mr = 6 + random()*Math.max(10,w*0.24);
    const mm = ctx.createRadialGradient(mx,my,0,mx,my,mr);
    const warm = shade ? 'rgba(150,140,160,' : 'rgba(195,175,140,';
    mm.addColorStop(0, warm + (0.05+random()*0.12)+')');
    mm.addColorStop(1, warm+'0)');
    ctx.fillStyle = mm;
    ctx.beginPath();
    ctx.ellipse(mx,my,mr,mr*0.7,0,0,Math.PI*2);
    ctx.fill();
  }
  // stained base
  const baseG = ctx.createLinearGradient(0,baseY-h*0.18,0,baseY);
  baseG.addColorStop(0,'rgba(120,100,80,0)');
  baseG.addColorStop(1,'rgba(100,80,60,0.25)');
  ctx.fillStyle = baseG;
  ctx.fillRect(left, baseY-h*0.2, w, h*0.2);
  ctx.restore();

  // sunlit edge
  if(!shade){
    lightEdge(left+leanL+1, topY+3, left-1, baseY-2, 2.4, '#fff6dc', 0.85);
  } else {
    lightEdge(right+leanU-1, topY+3, right+1, baseY-2, 1.6, '#e6d8c0', 0.4);
  }

  // roof — overhang, terracotta
  const over = w*0.13;
  const roofH = h*0.15;
  ctx.beginPath();
  ctx.moveTo(left-leanL*0.3-over, topY+4);
  ctx.lineTo(left+leanU*0.3-over*0.6, topY-roofH*0.35);
  ctx.lineTo(cx+leanU*0.4, topY-roofH);
  ctx.lineTo(right+leanL*0.3+over*0.6, topY-roofH*0.35);
  ctx.lineTo(right-leanU*0.3+over, topY+4);
  ctx.closePath();
  const rg = ctx.createLinearGradient(0,topY-roofH,0,topY+6);
  rg.addColorStop(0, roofColor);
  rg.addColorStop(0.6, roofB);
  rg.addColorStop(1, '#7f3a24');
  ctx.fillStyle = rg;
  ctx.fill();

  // roof tiles
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(left-over, topY+4);
  ctx.lineTo(cx, topY-roofH);
  ctx.lineTo(right+over, topY+4);
  ctx.closePath();
  ctx.clip();
  ctx.globalAlpha = 0.4;
  const tiles = Math.max(4, Math.floor(w/7));
  for(let i=0;i<tiles;i++){
    const t = (i+0.5)/tiles;
    ctx.strokeStyle = i%2 ? '#7a2e1a' : '#e0a078';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(lerp(left-over, cx, t), topY+4);
    ctx.lineTo(lerp(cx, right+over, t), topY-roofH);
    ctx.stroke();
  }
  ctx.restore();

  // chimney
  if(random()<0.55){
    const chx = cx + (random()-0.5)*w*0.4;
    const chH = roofH*(0.7+random()*0.6);
    ctx.fillStyle = shade ? '#a0909a' : '#e0d4c0';
    ctx.fillRect(chx-3, topY-roofH-chH+4, 6, chH);
    ctx.fillStyle = roofB;
    ctx.fillRect(chx-5, topY-roofH-chH+2, 10, 3);
  }

  // windows
  const winRows = h > 90 ? 2 : 1;
  const winCols = w > 110 ? 2 : 1;
  const wW = w*0.16;
  const wH = h*0.17;
  for(let r=0;r<winRows;r++){
    for(let c=0;c<winCols;c++){
      const wx = left + w*0.14 + c*(w*0.62/Math.max(1,winCols-1)) * (winCols>1?1:0) + (winCols===1? w*0.28:0);
      const wy = topY + h*0.14 + r*(h*0.30);
      if(random()<0.12) continue;
      // recess shadow
      ctx.fillStyle = 'rgba(50,45,70,0.3)';
      ctx.fillRect(wx-1.5, wy-1.5, wW+3, wH+3);
      // dark opening
      ctx.fillStyle = shade ? '#2a2846' : '#3a3550';
      ctx.fillRect(wx, wy, wW, wH);
      // glass warm reflection
      ctx.fillStyle = 'rgba(220,200,160,0.3)';
      ctx.fillRect(wx+1, wy+1, wW*0.4, wH*0.5);
      // frame
      ctx.strokeStyle = 'rgba(245,238,215,0.75)';
      ctx.lineWidth = 1;
      ctx.strokeRect(wx, wy, wW, wH);
      ctx.beginPath();
      ctx.moveTo(wx+wW*0.5, wy);
      ctx.lineTo(wx+wW*0.5, wy+wH);
      ctx.stroke();
      // shutters
      if(random()<0.6){
        ctx.fillStyle = random()<0.5 ? '#5a7284' : '#7a5a3a';
        ctx.fillRect(wx-wW*0.24, wy, wW*0.22, wH);
        ctx.fillRect(wx+wW+wW*0.02, wy, wW*0.22, wH);
      }
    }
  }

  // balcony
  if(h>110 && random()<0.65){
    const bx = cx + (random()-0.5)*w*0.2;
    const by = topY + h*0.52;
    const bw = w*0.5;
    ctx.fillStyle = 'rgba(40,35,55,0.3)';
    ctx.fillRect(bx-bw/2, by+8, bw, 6);
    ctx.fillStyle = shade ? '#b8adb0' : '#ecdfc6';
    ctx.fillRect(bx-bw/2, by, bw, 8);
    // railing
    ctx.strokeStyle = 'rgba(60,55,75,0.6)';
    ctx.lineWidth = 1.1;
    for(let i=0;i<8;i++){
      const rx = bx-bw/2 + i*(bw/7);
      ctx.beginPath();
      ctx.moveTo(rx, by+2);
      ctx.lineTo(rx, by-13);
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.moveTo(bx-bw/2, by-13);
    ctx.lineTo(bx+bw/2, by-13);
    ctx.stroke();
    // railing top bar
    ctx.beginPath();
    ctx.moveTo(bx-bw/2, by-4);
    ctx.lineTo(bx+bw/2, by-4);
    ctx.stroke();
    // plant on balcony
    const px = bx+(random()-0.5)*bw*0.5;
    const py = by-13;
    ctx.fillStyle = '#4a6b3e';
    for(let k=0;k<7;k++){
      ctx.beginPath();
      ctx.ellipse(px+(random()-0.5)*14, py-random()*10, 3.5+random()*3, 2.5+random()*3, random()*Math.PI, 0, Math.PI*2);
      ctx.fill();
    }
    if(random()<0.5){
      ctx.fillStyle = '#c04a7a';
      for(let k=0;k<5;k++){
        ctx.beginPath();
        ctx.arc(px+(random()-0.5)*10, py-random()*8, 2, 0, Math.PI*2);
        ctx.fill();
      }
    }
  }

  // base plants
  if(random()<0.55){
    const px = left + random()*w;
    ctx.fillStyle = 'rgba(60,85,50,0.85)';
    for(let k=0;k<7;k++){
      ctx.beginPath();
      ctx.ellipse(px+(random()-0.5)*20, baseY - random()*16, 3+random()*3, 2+random()*2, random()*Math.PI, 0, Math.PI*2);
      ctx.fill();
    }
  }
}

// ---------- village cluster (asymmetric, staggered) ----------
function drawCypress(x, baseY, hgt, alpha){
  ctx.save();
  ctx.globalAlpha = alpha===undefined?1:alpha;
  ctx.fillStyle = '#3a5a40';
  const segs = 7;
  for(let s=0;s<segs;s++){
    const t = s/segs;
    const y = baseY - hgt*t;
    const rw = (1-t)*hgt*0.14 + 2;
    const rseed = ((x*7+s*13)|0)%17;
    const jx = Math.sin(rseed+x)*rw*0.3;
    ctx.beginPath();
    ctx.ellipse(x+jx, y, rw, rw*1.3, 0, 0, Math.PI*2);
    ctx.fill();
  }
  ctx.fillStyle = 'rgba(70,100,60,0.6)';
  for(let s=0;s<segs;s++){
    const t = s/segs;
    const y = baseY - hgt*t;
    const rw = (1-t)*hgt*0.10 + 1;
    ctx.beginPath();
    ctx.ellipse(x-rw*0.4, y, rw*0.7, rw*1.0, 0, 0, Math.PI*2);
    ctx.fill();
  }
  ctx.restore();
}

function paintVillage(){
  // left hillside mass (soil/vegetation base beneath houses)
  ctx.beginPath();
  ctx.moveTo(0, H_*0.42);
  ctx.lineTo(W_*0.10, H_*0.48);
  ctx.lineTo(W_*0.22, H_*0.56);
  ctx.lineTo(W_*0.26, H_*0.66);
  ctx.lineTo(W_*0.20, H_*0.78);
  ctx.lineTo(W_*0.10, H_*0.88);
  ctx.lineTo(0, H_*0.95);
  ctx.lineTo(0, H_*0.42);
  ctx.closePath();
  const hg = ctx.createLinearGradient(0,H_*0.42,0,H_*0.95);
  hg.addColorStop(0,'#a89478');
  hg.addColorStop(0.5,'#8a7658');
  hg.addColorStop(1,'#6a5840');
  ctx.fillStyle = hg;
  ctx.fill();

  // scrub on hillside (before houses so houses sit on top)
  for(let i=0;i<260;i++){
    const x = random()*W_*0.30;
    const y = H_*0.46 + random()*H_*0.40;
    // only if on hill mass roughly
    const r = 2 + random()*6;
    ctx.fillStyle = `rgba(${55+random()*40|0},${75+random()*40|0},${45+random()*25|0},0.7)`;
    ctx.beginPath();
    ctx.ellipse(x,y, r, r*0.75, random()*Math.PI, 0, Math.PI*2);
    ctx.fill();
  }

  // --- far back houses (hazy, small) ---
  ctx.save();
  for(let i=0;i<10;i++){
    const cx = W_*0.02 + random()*W_*0.32;
    const baseY = H_*0.48 + random()*H_*0.04;
    const w = 22 + random()*30;
    const h = 22 + random()*26;
    ctx.globalAlpha = 0.7;
    drawHouse(cx, baseY, w, h, false, '#b56a4a', i);
  }
  ctx.restore();

  // --- staggered mid-ground clusters (compact, asymmetric) ---
  const clusters = [
    // [cx, baseY, w, h, shade, roof, castShadow]
    {x:W_*0.04, y:H_*0.52, w:60, h:62, shade:true,  roof:'#b95a38'},
    {x:W_*0.10, y:H_*0.535,w:70, h:74, shade:false, roof:roofA},
    {x:W_*0.16, y:H_*0.545,w:52, h:58, shade:true,  roof:roofB},
    {x:W_*0.07, y:H_*0.55, w:82, h:88, shade:false, roof:roofC},
    {x:W_*0.13, y:H_*0.565,w:74, h:82, shade:true,  roof:roofA},

    {x:W_*0.04, y:H_*0.60, w:88, h:100, shade:false, roof:roofB},
    {x:W_*0.12, y:H_*0.605,w:94, h:108, shade:true,  roof:roofA},
    {x:W_*0.19, y:H_*0.595,w:66, h:78,  shade:false, roof:roofC},

    {x:W_*0.05, y:H_*0.665,w:110,h:124, shade:true,  roof:roofA},
    {x:W_*0.14, y:H_*0.675,w:120,h:138, shade:false, roof:roofB},
    {x:W_*0.21, y:H_*0.66, w:80, h:94,  shade:true,  roof:roofC},

    {x:W_*0.04, y:H_*0.76, w:130,h:150, shade:false, roof:roofC},
    {x:W_*0.14, y:H_*0.77, w:140,h:158, shade:true,  roof:roofA},
    {x:W_*0.22, y:H_*0.745,w:96, h:112, shade:false, roof:roofB},
  ];
  for(let i=0;i<clusters.length;i++){
    const c = clusters[i];
    drawHouse(c.x, c.y, c.w, c.h, c.shade, c.roof, i, {castShadow:true});
    // occasional cypress next to house
    if(i%3===1){
      drawCypress(c.x + c.w*0.55, c.y + 4, c.h*0.55, 0.9);
    }
  }

  // some cypresses between
  drawCypress(W_*0.01, H_*0.68, 70, 0.9);
  drawCypress(W_*0.09, H_*0.60, 60, 0.85);
  drawCypress(W_*0.18, H_*0.55, 50, 0.75);

  // --- foreground larger houses lower-left ---
  drawHouse(W_*0.06, H_*0.90, 150, 165, false, roofA, 7, {castShadow:true});
  drawHouse(W_*0.18, H_*0.94, 165, 180, true,  roofB, 8, {castShadow:true});
  // small house tucked behind
  drawHouse(W_*0.24, H_*0.88, 110, 128, false, roofC, 9, {castShadow:true});
}

// ---------- stair lane foreground ----------
function paintStairs(){
  // ground mass foreground lower-left
  ctx.beginPath();
  ctx.moveTo(0, H_*0.78);
  ctx.lineTo(W_*0.06, H_*0.76);
  ctx.lineTo(W_*0.14, H_*0.80);
  ctx.lineTo(W_*0.22, H_*0.86);
  ctx.lineTo(W_*0.24, H_*0.94);
  ctx.lineTo(W_*0.18, H_);
  ctx.lineTo(0, H_);
  ctx.closePath();
  const gg = ctx.createLinearGradient(0,H_*0.76,0,H_);
  gg.addColorStop(0,'#b09878');
  gg.addColorStop(1,'#7a6450');
  ctx.fillStyle = gg;
  ctx.fill();

  // zigzag stair path
  const path = [
    [W_*0.02, H_*0.98],
    [W_*0.08, H_*0.92],
    [W_*0.13, H_*0.86],
    [W_*0.19, H_*0.80],
    [W_*0.24, H_*0.74],
    [W_*0.28, H_*0.68],
  ];
  ctx.save();
  ctx.beginPath();
  ctx.moveTo(path[0][0]-30, path[0][1]+20);
  for(let i=0;i<path.length;i++) ctx.lineTo(path[i][0], path[i][1]);
  ctx.lineTo(path[path.length-1][0]+22, path[path.length-1][1]-12);
  ctx.lineTo(path[path.length-1][0]+90, H_);
  ctx.lineTo(W_*0.02, H_);
  ctx.closePath();
  const pg = ctx.createLinearGradient(0,H_*0.68,W_*0.3,H_);
  pg.addColorStop(0,'#d4be9e');
  pg.addColorStop(0.5,'#b59d80');
  pg.addColorStop(1,'#8e7a5f');
  ctx.fillStyle = pg;
  ctx.fill();

  // irregular stone steps
  for(let i=0;i<path.length-1;i++){
    const [x1,y1] = path[i];
    const [x2,y2] = path[i+1];
    const stepsN = 6 + i*2;
    for(let s=0;s<stepsN;s++){
      const t = (s+0.5)/stepsN;
      const sx = lerp(x1,x2,t) + (random()-0.5)*16;
      const sy = lerp(y1,y2,t) + (random()-0.5)*4;
      const sw = 22 + random()*34 + i*9;
      const sh = 3 + random()*4 + i*0.9;
      ctx.fillStyle = random()<0.45 ? 'rgba(240,225,200,0.6)' : 'rgba(130,112,90,0.6)';
      ctx.beginPath();
      ctx.moveTo(sx-sw*0.5, sy+sh*0.5);
      ctx.lineTo(sx-sw*0.44+random()*4, sy-sh*0.5);
      ctx.lineTo(sx+sw*0.5, sy-sh*0.4);
      ctx.lineTo(sx+sw*0.42+random()*4, sy+sh*0.55);
      ctx.closePath();
      ctx.fill();
      ctx.strokeStyle = 'rgba(255,245,220,0.4)';
      ctx.lineWidth = 0.6;
      ctx.beginPath();
      ctx.moveTo(sx-sw*0.4, sy-sh*0.5);
      ctx.lineTo(sx+sw*0.5, sy-sh*0.4);
      ctx.stroke();
    }
  }
  ctx.restore();

  // stone retaining edges along path (low patchy walls)
  for(let i=0;i<path.length-1;i++){
    const [x1,y1] = path[i];
    const [x2,y2] = path[i+1];
    const segs = 8;
    for(let s=0;s<segs;s++){
      const t = s/segs;
      const px = lerp(x1,x2,t) - 14 - random()*8;
      const py = lerp(y1,y2,t) + 12;
      ctx.fillStyle = `rgba(${140+random()*40|0},${120+random()*30|0},${95+random()*25|0},0.85)`;
      ctx.beginPath();
      ctx.ellipse(px, py, 8+random()*10, 4+random()*4, (random()-0.5)*0.4, 0, Math.PI*2);
      ctx.fill();
    }
  }
}

// ---------- foreground flowers (lower-left cluster only) ----------
function paintBougainvillea(){
  const clusters = [
    {x:W_*0.03, y:H_*0.92, r:95, n:130},
    {x:W_*0.015,y:H_*0.80, r:70, n:85},
    {x:W_*0.10, y:H_*0.985,r:80, n:90},
  ];
  for(const cl of clusters){
    // dark foliage base
    ctx.save();
    for(let i=0;i<cl.n*0.55;i++){
      const a = random()*Math.PI*2;
      const rr = Math.pow(random(),0.6)*cl.r;
      const x = cl.x + Math.cos(a)*rr;
      const y = cl.y + Math.sin(a)*rr*0.8;
      ctx.fillStyle = `rgba(${30+random()*30|0},${50+random()*30|0},${30+random()*20|0},0.8)`;
      ctx.beginPath();
      ctx.ellipse(x,y, 4+random()*6, 3+random()*4, a, 0, Math.PI*2);
      ctx.fill();
    }
    // magenta petals
    const magPalette = ['#c62d72','#e8489a','#b02460','#f062a8','#a01f55','#d84a89'];
    for(let i=0;i<cl.n;i++){
      const a = random()*Math.PI*2;
      const rr = Math.pow(random(),0.55)*cl.r;
      const x = cl.x + Math.cos(a)*rr;
      const y = cl.y + Math.sin(a)*rr*0.8;
      ctx.fillStyle = magPalette[(random()*magPalette.length)|0];
      ctx.globalAlpha = 0.78 + random()*0.22;
      ctx.beginPath();
      ctx.ellipse(x,y, 3+random()*5, 2.5+random()*4, random()*Math.PI, 0, Math.PI*2);
      ctx.fill();
    }
    // highlights
    ctx.globalAlpha = 0.6;
    for(let i=0;i<cl.n*0.22;i++){
      const a = random()*Math.PI*2;
      const rr = Math.pow(random(),0.5)*cl.r*0.9;
      const x = cl.x + Math.cos(a)*rr;
      const y = cl.y + Math.sin(a)*rr*0.8 - 6;
      ctx.fillStyle = '#ffb8d8';
      ctx.beginPath();
      ctx.arc(x,y, 1.5+random()*2, 0, Math.PI*2);
      ctx.fill();
    }
    ctx.restore();
    ctx.globalAlpha = 1;
  }
}

// ---------- global light / vignette ----------
function paintGlobalLight(){
  ctx.save();
  ctx.globalCompositeOperation = 'overlay';
  const g = ctx.createRadialGradient(W_*0.14,H_*0.10,40,W_*0.14,H_*0.10,W_*0.75);
  g.addColorStop(0,'rgba(255,220,150,0.28)');
  g.addColorStop(0.5,'rgba(255,210,160,0.10)');
  g.addColorStop(1,'rgba(120,150,200,0.10)');
  ctx.fillStyle = g;
  ctx.fillRect(0,0,W_,H_);
  ctx.restore();

  ctx.save();
  const v = ctx.createRadialGradient(W_*0.5,H_*0.5,H_*0.3,W_*0.5,H_*0.5,H_*0.9);
  v.addColorStop(0,'rgba(0,0,0,0)');
  v.addColorStop(1,'rgba(30,20,10,0.26)');
  ctx.fillStyle = v;
  ctx.fillRect(0,0,W_,H_);
  ctx.restore();
}

